body.query:
query($a: String!, $chain: Int!) { vaultByAddress(address: $a, chainId: $chain) { 
  address
  name
  listed
  asset { symbol address price { usd } }
  liquidity { usd }
  warnings { type level }
  state { totalAssetsUsd netApy fee timelock guardian curators { name }
          allocation { supplyAssetsUsd market { marketId } } }
 } }
